import { MeshStandardNodeMaterial, PlaneGeometry, Mesh, Group, Color } from 'three/webgpu';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const group = new Group();
  group.userData.cleanupList = [];

  // Colors from visual spec
  const SURFACE = new Color('#0b0b10');
  const ACCENT = new Color('#ff2a38');

  // Tessellated plane geometry for displacement
  const geom = new PlaneGeometry(2, 1.25, 64, 64);
  const mat = new MeshStandardNodeMaterial({
    color: SURFACE,
    roughness: 0.6,
    metalness: 0.5,
    emissive: ACCENT,
    emissiveIntensity: 0
  });
  const mesh = new Mesh(geom, mat);
  group.add(mesh);

  // Load textures (asynchronous, cached)
  const loadTextures = Promise.all([
    ctx.textureLoader.loadTexture(config.imageUrl),
    ctx.textureLoader.loadTexture(config.depthMapUrl)
  ]);

  loadTextures.then(([baseTex, depthTex]) => {
    mat.map = baseTex;
    mat.displacementMap = depthTex;
    mat.displacementScale = 0.04;
    mat.needsUpdate = true;

    // Apply all cinematic primitives from config
    for (const prim of (config.cinematicPrimitives || [])) {
      const result = ctx.primitives[prim.name](mesh, prim.params || {});
      if (result && result.cleanup) {
        group.userData.cleanupList.push(result.cleanup);
      }
    }
  });

  // Hover: subtle rise-in effect
  mesh.userData.handlers = {
    mouseenter: () => {
      gsap.to(mesh.position, {
        y: 0.15,
        duration: 0.3,
        ease: 'power2.out'
      });
    },
    mouseleave: () => {
      gsap.to(mesh.position, {
        y: 0,
        duration: 0.3,
        ease: 'power2.out'
      });
    },
    click: () => {
      // Press-down scale animation
      gsap.to(mesh.scale, {
        x: 0.97,
        y: 0.97,
        z: 0.97,
        duration: 0.12,
        ease: 'back.out',
        yoyo: true,
        repeat: 1
      });
      // Emit navigation event
      ctx.emit('hub-features.select', {});
    }
  };

  // Cleanup function
  group.userData.cleanup = () => {
    gsap.killTweensOf(mesh.position);
    gsap.killTweensOf(mesh.scale);
    (group.userData.cleanupList || []).forEach(fn => fn());
    geom.dispose();
    mat.dispose();
    // Note: textures are cached by ctx, dispose handled externally
  };

  return group;
}
